import SwiftUI
import PhotosUI // 端末の写真を選択するために使用します
// 選択された画像を管理するためのデータ構造
struct SelectedPhoto: Identifiable, Equatable {
let id = UUID()
var image: Image
// 実際のアプリではUIImageなどを保持して保存処理等に使用します
}
struct ContentView: View {
// MARK: - 状態変数
// pictureListSelected に表示される選択済み写真の配列（最大9枚）
@State private var selectedPhotos: [SelectedPhoto] = []
// ドラッグ＆ドロップ操作中のアイテムを保持する変数
@State private var draggedPhoto: SelectedPhoto?
// 端末の写真ピッカーで選択されたアイテム
@State private var pickerItems: [PhotosPickerItem] = []
// MARK: - メインビュー
// 仕様: 画面は縦位置のみで、横位置にはならない。
// ※ 画面の縦位置固定はUIコードではなく、Xcodeのプロジェクト設定 (Info.plistの「Supported interface orientations」) にて「Portrait」のみにチェックを入れることで実現します。
var body: some View {
VStack(spacing: 15) {
// 1. 保存ボタンエリア
// 仕様: そのうえに、ボタンなどを配置します。ボタンはひとつあります。
// 仕様: ボタンの名前は"buttonSaveCollage"です。
HStack {
Spacer()
Button(action: {
// 仕様: buttonSaveCollage ボタンを押すと、collagePreviewに表示されているイメージを端末に保存します。
saveCollage()
}) {
Text("保存")
.fontWeight(.bold)
.padding(.horizontal, 20)
.padding(.vertical, 10)
.background(Color.blue)
.foregroundColor(.white)
.cornerRadius(8)
}
.accessibilityIdentifier("buttonSaveCollage")
}
// 2. コラージュプレビューエリア
// 仕様: その上に、写真をコラージュするエリアがあります。このエリアの名前を"collagePreview"とします。
collagePreview
.frame(maxWidth: .infinity, maxHeight: .infinity)
.background(Color.gray.opacity(0.1))
.border(Color.gray, width: 1)
.accessibilityIdentifier("collagePreview")
// 3. 選択済み写真リストエリア
// 仕様: その上に、選択された写真のリストを縮小イメージで一覧表示します。このエリアの名前を"pictureListSelected"とします。
pictureListSelected
.frame(height: 120)
.background(Color.yellow.opacity(0.1))
.accessibilityIdentifier("pictureListSelected")
// 4. 写真選択エリア
// 仕様: 画面下部に、端末に保存されている写真の一覧が表示される。このエリアの名前を"pictureListToSelect" とする。
pictureListToSelect
.frame(height: 100)
.background(Color.green.opacity(0.1))
.accessibilityIdentifier("pictureListToSelect")
}
.padding()
}
// MARK: - 各エリアのView定義
// ▼ コラージュプレビュー
private var collagePreview: some View {
// 仕様: pictureListSelectedに表示されている写真は、collagePreviewに並べて表示されます。
// 仕様: 縦・横、それぞれの最大枚数は３枚です。選択できる写真の枚数は、最大９枚です。
GeometryReader { geometry in
let totalCount = selectedPhotos.count
if totalCount == 0 {
Text("写真を選択してください")
.frame(maxWidth: .infinity, maxHeight: .infinity)
.foregroundColor(.gray)
} else {
// 仕様: 選択された枚数が偶数であれば、均等に割り付けて並べます。
// 仕様: 奇数の場合は、右側が１枚多くなります。
// ※ この仕様を満たすため、グリッドの列数を計算してレイアウトします。
let columnsCount = calculateColumns(for: totalCount)
let columns = Array(repeating: GridItem(.flexible(), spacing: 5), count: columnsCount)
LazyVGrid(columns: columns, spacing: 5) {
ForEach(selectedPhotos) { photo in
photo.image
.resizable()
.scaledToFill()
.frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity)
.aspectRatio(1, contentMode: .fit)
.clipped()
}
}
}
}
}
// ▼ 選択済み写真リスト (ドラッグ＆ドロップ対応)
private var pictureListSelected: some View {
// 仕様: 写真は、横方向に追加されます。
ScrollView(.horizontal, showsIndicators: false) {
HStack(spacing: 10) {
// 仕様: 一番左側にはゴミ箱のアイコンがあり、このうえにドラッグアンドドロップすると、選択された画像の選択解除は、pictureListSelectedに表示されている画像となります。
Image(systemName: "trash")
.font(.largeTitle)
.foregroundColor(.red)
.frame(width: 80, height: 80)
.background(Color.gray.opacity(0.2))
.cornerRadius(8)
.onDrop(of: [.text], isTargeted: nil) { providers in
// ゴミ箱にドロップされた時の削除処理
if let draggedPhoto = draggedPhoto {
selectedPhotos.removeAll { $0.id == draggedPhoto.id }
}
return true
}
// 仕様: pictureToSelect で選択された写真は、pictureListSelectedに一覧表示します。
ForEach(selectedPhotos) { photo in
// 仕様: pictureListSelectedの画像サイズは、左右それぞれに並べた画像高さ・幅の平均です。
// (※ここでは縮小サムネイルとして固定サイズ(80x80)を割り当てています。実際の平均計算は画像データロード時に行います)
photo.image
.resizable()
.scaledToFill()
.frame(width: 80, height: 80)
.clipped()
.cornerRadius(8)
// 仕様: pictureListSelectedで表示された写真の順番は、自由に変えることができます。
// 画像を左右にドラッグアンドドロップする要領で並び替えます。
.onDrag {
self.draggedPhoto = photo
return NSItemProvider(object: photo.id.uuidString as NSString)
}
.onDrop(of: [.text], delegate: DropViewDelegate(item: photo, items: $selectedPhotos, draggedItem: $draggedPhoto))
}
}
.padding(.horizontal)
}
}
// ▼ 端末写真選択エリア
private var pictureListToSelect: some View {
// 仕様: 端末に保存されている写真を選択する機能があります。
// iOS標準のPhotosPickerを使用して実装します。
HStack {
PhotosPicker(
selection: $pickerItems,
maxSelectionCount: 9 - selectedPhotos.count, // 仕様: 選択できる写真の枚数は、最大９枚です。
matching: .images,
photoLibrary: .shared()
) {
VStack {
Image(systemName: "photo.on.rectangle.angled")
.font(.largeTitle)
Text("端末から写真を追加")
.font(.caption)
}
.frame(maxWidth: .infinity, maxHeight: .infinity)
.foregroundColor(.blue)
}
.onChange(of: pickerItems) { _ in
loadPhotosFromPicker()
}
}
}
// MARK: - ヘルパー関数
// 奇数・偶数の列数計算ロジック
private func calculateColumns(for count: Int) -> Int {
// 例: 1枚なら1列、2〜4枚なら2列、5〜9枚なら3列（最大縦横3枚）
if count <= 1 { return 1 }
if count <= 4 { return 2 }
return 3
// ※ 奇数の場合に「右側が1枚多くなる」複雑なレイアウトを行う場合は、
// ここでカスタムレイアウト(GeometryReaderを駆使したHStack/VStack)を構築する必要がありますが、
// スケルトンとしては汎用的なGridを使用しています。
}
// ピッカーから写真を読み込むダミー関数
private func loadPhotosFromPicker() {
// 実際のアプリでは pickerItems からデータ(Data)を読み込み、Imageを生成してselectedPhotosに追加します。
// 仕様: pictureToSelect で選択された写真は、pictureListSelectedに一覧表示します。
print("写真をロードして selectedPhotos に追加する処理をここに記述します。")
}
// 保存処理のダミー関数
private func saveCollage() {
// 仕様: collagePreviewに表示されているイメージを端末に保存します。
// iOS 16以降であれば `ImageRenderer` を使用して `collagePreview` View自体をUIImageに変換し、
// `UIImageWriteToSavedPhotosAlbum` で写真アプリに保存します。
print("collagePreviewを画像化して端末に保存する処理をここに記述します。")
}
}
// MARK: - ドラッグ＆ドロップ並び替え用のデリゲート
struct DropViewDelegate: DropDelegate {
let item: SelectedPhoto
@Binding var items: [SelectedPhoto]
@Binding var draggedItem: SelectedPhoto?
func performDrop(info: DropInfo) -> Bool {
draggedItem = nil
return true
}
func dropEntered(info: DropInfo) {
guard let draggedItem = self.draggedItem else { return }
if draggedItem != item {
let from = items.firstIndex(of: draggedItem)!
let to = items.firstIndex(of: item)!
withAnimation(.default) {
self.items.move(fromOffsets: IndexSet(integer: from), toOffset: to > from ? to + 1 : to)
}
}
}
}
